@startuml

class OOBank {
  + Name : string
}

class Branch {
  + Address : string
  + BranchNumber : string
}

class Division {
  + Name : string
}

class Subdivision {
  + Name : string
}

class Employee {
  + Name : string
}

class Client {
  + Name : string
}

class Account {
  + AccountNumber : string
  + Balance : double
  + CreditLimit : double
  + InterestRate : float
  + MonthlyFee : float
  + Privileges : string[]
}

class MortgageAccount extends Account {
  + PropertyCollateral : string
}

class CheckingAccount extends Account {
}

class CreditCardAccount extends Account {
  + ExpiryDate : date
}

class SecondaryCard {
}

Employee "1" -- "0..*" Client : personal banker
Employee "1" -- "0..*" Employee : manages
Division "1" -- "0..*" Employee : employs
Division "1" -- "0..*" Division : contains
Subdivision "1" -- "0..*" Subdivision : contains
Subdivision "1" -- "0..*" Branch : contains
Division "1" -- "0..*" Branch : contains
Branch "1" -- "0..*" Account : opens
Client "1..*" -- "1..*" Account : owns
CreditCardAccount "1" -- "0..*" SecondaryCard : has

@enduml

